Issues.Body:
When an imported `@Input({ transform })` function's first parameter references exported or imported named types (e.g. `export function toCustom(v: CustomConfig | string): CustomConfig`), `UnexportedTypeFinder` previously marked `is_self_contained = false` for any non-ambient `TSTypeReference` and fell back to `Parameters<typeof toCustom>[0]` instead of emitting the namespace-qualified type (`i1.CustomConfig | string`) like `ngtsc`.

This change:
1. Tracks qualifiable `TSTypeReference` identifiers in `FirstParam::Typed` (`ng-analyze/src/analyzer/transforms.rs`) and resolves their consumer module specifiers in Stage 2 via `ReferenceEmitStrategy`.
2. Records the UTF-16 insertion offsets on `ClassMetadata.coercionNamespaceInsertions` (`ng-analyze/src/analyzer/class_data.rs`) and splices `<ns>.` namespace prefixes in `processor.ts` (`renderCoercionMembers`).

### Input
```ts
// transforms.ts
export interface CustomConfig {
  id: string;
}
export function toCustom(value: CustomConfig | string): CustomConfig {
  return typeof value === 'string' ? {id: value} : value;
}

// test.ts
import {Component, Input} from '@angular/core';
import {toCustom, CustomConfig} from './transforms';

@Component({
  selector: 'transform-cmp',
  template: '',
})
export class TransformCmp {
  @Input({transform: toCustom}) custom!: CustomConfig;
}
```

### Output before the fix (`ngp`)
```ts
import {Component, Input} from '@angular/core';
import {toCustom, CustomConfig} from './transforms';
// @ts-ignore
import * as i0 from '@angular/core';

export class TransformCmp {
  custom!: CustomConfig;
  // ...
  // @ts-ignore
  declare static ngAcceptInputType_custom: Parameters<typeof toCustom>[0];
}
```

### Output after the fix (`ngp` — matches `ngtsc`)
```ts
import {Component, Input} from '@angular/core';
import {toCustom, CustomConfig} from './transforms';
// @ts-ignore
import * as i0 from '@angular/core';
// @ts-ignore
import * as i1 from './transforms';

export class TransformCmp {
  custom!: CustomConfig;
  // ...
  // @ts-ignore
  declare static ngAcceptInputType_custom: i1.CustomConfig | string;
}
```

In `ngtsc`, external component resources (`templateUrl`, `styleUrl`, `styleUrls`, and `<link rel="stylesheet">`) are loaded via `CompilerHost.readFile` (`ts.sys.readFile`), which strips a leading UTF-8 byte order mark (`\uFEFF`).

In `ng-analyze`, `ResourceResolver::load_resource` previously read files via `read_to_string` without stripping a leading `\u{feff}`, causing `\uFEFF` to leak into compiled `ɵcmp.styles` selectors (`\uFEFF.box[_ngcontent-%COMP%]`) and `ɵsetClassMetadata` `template`/`styles` strings. This change strips a leading `\u{feff}` in `ResourceResolver::load_resource`.

### Input

**`app.component.ts`**:
```ts
import { Component } from '@angular/core';
@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {}
```

**`app.component.html`** (starts with UTF-8 BOM `\uFEFF`):
```html
\uFEFF<div>Hello</div>
```

**`app.component.css`** (starts with UTF-8 BOM `\uFEFF`):
```css
\uFEFF.box { color: red; }
```

### Output Before Fix (`ngp`)

```ts
export class AppComponent {
  // ...
  static ɵcmp = /*@__PURE__*/ i0.ɵɵdefineComponent({
    type: AppComponent,
    selectors: [['app-root']],
    decls: 2,
    vars: 0,
    template: function AppComponent_Template(rf: number, ctx: any): any {
      if (rf & 1) {
        i0.ɵɵelementStart(0, 'div');
        i0.ɵɵtext(1, 'Hello');
        i0.ɵɵelementEnd();
      }
    },
    styles: ['\uFEFF.box[_ngcontent-%COMP%] {\n  color: red;\n}'],
  });
  static {
    (typeof ngDevMode === 'undefined' || ngDevMode) &&
      i0.ɵsetClassMetadata(
        AppComponent,
        [
          {
            type: Component,
            args: [
              {
                selector: 'app-root',
                template: '\uFEFF<div>Hello</div>',
                styles: ['\uFEFF.box { color: red; }'],
              },
            ],
          },
        ],
        null,
        null,
      );
  }
}
```

### Output After Fix (`ngp`, matching `ngtsc`)

```ts
export class AppComponent {
  // ...
  static ɵcmp = /*@__PURE__*/ i0.ɵɵdefineComponent({
    type: AppComponent,
    selectors: [['app-root']],
    decls: 2,
    vars: 0,
    template: function AppComponent_Template(rf: number, ctx: any): any {
      if (rf & 1) {
        i0.ɵɵelementStart(0, 'div');
        i0.ɵɵtext(1, 'Hello');
        i0.ɵɵelementEnd();
      }
    },
    styles: ['.box[_ngcontent-%COMP%] {\n  color: red;\n}'],
  });
  static {
    (typeof ngDevMode === 'undefined' || ngDevMode) &&
      i0.ɵsetClassMetadata(
        AppComponent,
        [
          {
            type: Component,
            args: [
              {
                selector: 'app-root',
                template: '<div>Hello</div>',
                styles: ['.box { color: red; }'],
              },
            ],
          },
        ],
        null,
        null,
      );
  }
}
```

When wrapping `ɵsetClassMetadata` inside a `static { ... }` block, `createStaticBlock` previously prepended 4 spaces to every non-empty line via `statement.split('\n').map((line) => (line.length > 0 ? \`    \${line}\` : line)).join('\n')`.

When a component decorator slices a multiline backtick template literal (e.g. `template: \`...\``), indenting continuation lines inside the template literal mutates the runtime string value passed to `ɵsetClassMetadata` compared to `ngtsc`. This change updates `createStaticBlock` to skip 4-space continuation indentation while inside template/string literals.

