When downleveling member decorators into `static propDecorators` on `jit: true` classes, pass `classMeta.laterDeclarationReferences` (when not in compliance mode) to `buildDecoratorMetadataExpr`.

Without `jitGuards`, a forward reference to a class declared later in the same file inside `static propDecorators` is not preceded by `// @ts-ignore`, causing `tsc` to report `TS2449: Class '...' used before its declaration` whenever `static propDecorators` spans multiple lines (whereas `ngtsc` runs `downlevelDecoratorsTransform` during JS emit after typechecking and produces matching runtime `propDecorators` metadata).

### Input

```ts
import {Component, Directive, ViewChild} from '@angular/core';

@Component({
  selector: 'jit-cmp',
  template: '',
  jit: true,
})
export class JitCmp {
  @ViewChild('tpl', {
    static: true,
  })
  tpl: any;

  @ViewChild(ForwardDir) child!: ForwardDir;
}

@Directive({
  selector: '[forward-dir]',
  jit: true,
})
export class ForwardDir {}
```

### Output Before Fix (`ngp`)

```ts
import {Component, Directive, ViewChild} from '@angular/core';
// @ts-ignore
import * as i0 from '@angular/core';

@Component({
  selector: 'jit-cmp',
  template: '',
  jit: true,
})
export class JitCmp {
  tpl: any;

  child!: ForwardDir;

  // @ts-ignore
  static propDecorators = {tpl: [{type: ViewChild, args: ['tpl', {
    static: true,
  }]}], child: [{type: ViewChild, args: [ForwardDir]}]};
}

@Directive({
  selector: '[forward-dir]',
  jit: true,
})
export class ForwardDir {}
```
*(Fails `tsc` with `TS2449: Class 'ForwardDir' used before its declaration.`)*

### Output After Fix (`ngp`, matching `ngtsc` after JS emit)

