  selector: 'jit-cmp',
  template: '',
  jit: true,
})
export class JitCmp {
  tpl: any;

  child!: ForwardDir;

  // @ts-ignore
  static propDecorators = {tpl: [{type: ViewChild, args: ['tpl', {
    static: true,
  }]}], child: [{type: ViewChild, args: [// @ts-ignore
ForwardDir]}]};
}

@Directive({
  selector: '[forward-dir]',
  jit: true,
